window.__TNPSC_REGISTER_TEST__("tamil", 5, [{"id":401,"subject":"tamil","testNumber":5,"question":"திருக்குறளின் முப்பால்களிலும் உள்ள அதிகாரங்களின் எண்ணிக்கை முறையே எவை?","options":["அறத்துப்பால் – 38, பொருட்பால் – 70, இன்பத்துப்பால் – 25","அறத்துப்பால் – 35, பொருட்பால் – 73, இன்பத்துப்பால் – 25","அறத்துப்பால் – 38, பொருட்பால் – 68, இன்பத்துப்பால் – 27","அறத்துப்பால் – 40, பொருட்பால் – 70, இன்பத்துப்பால் – 23"],"correctAnswer":0,"explanation":"திருக்குறள் மொத்தம் 133 அதிகாரங்களையும் 1,330 குறட்பாக்களையும் கொண்டது. இதில் அறத்துப்பால் 38 அதிகாரங்களையும், பொருட்பால் 70 அதிகாரங்களையும், இன்பத்துப்பால் (காமத்துப்பால்) 25 அதிகாரங்களையும் கொண்டுள்ளது.","difficulty":"easy","topic":"திருக்குறள் அமைப்பு"},{"id":402,"subject":"tamil","testNumber":5,"question":"திருக்குறளில் உள்ள மொத்த இயல்களின் எண்ணிக்கை எத்தனை?","options":["7 இயல்கள்","8 இயல்கள்","12 இயல்கள்","9 இயல்கள்"],"correctAnswer":3,"explanation":"திருக்குறள் மூன்று பால்களாகவும் மொத்தம் 9 இயல்களாகவும் பகுக்கப்பட்டுள்ளது. அறத்துப்பாலில் 4 இயல்களும், பொருட்பாலில் 3 இயல்களும், இன்பத்துப்பாலில் 2 இயல்களும் அமைந்துள்ளன.","difficulty":"easy","topic":"திருக்குறள் அமைப்பு"},{"id":403,"subject":"tamil","testNumber":5,"question":"திருக்குறளின் அறத்துப்பாலில் இடம்பெறும் நான்கு இயல்கள் எவை?","options":["பாயிரவியல், இல்லறவியல், துறவறவியல், ஊழியல்","பாயிரவியல், அரசியல், இல்லறவியல், துறவறவியல்","இல்லறவியல், துறவறவியல், அமைச்சியல், ஊழியல்","பாயிரவியல், களவியல், கற்பியல், ஊழியல்"],"correctAnswer":0,"explanation":"அறத்துப்பாலில் உள்ள 38 அதிகாரங்கள் நான்கு இயல்களாகப் பிரிக்கப்பட்டுள்ளன. அவை பாயிரவியல் (4 அதிகாரங்கள்), இல்லறவியல் (20 அதிகாரங்கள்), துறவறவியல் (13 அதிகாரங்கள்) மற்றும் ஊழியல் (1 அதிகாரம்) என்பனவாகும்.","difficulty":"medium","topic":"திருக்குறள் அமைப்பு"},{"id":404,"subject":"tamil","testNumber":5,"question":"திருக்குறள் எந்தப் பாவகையால் இயற்றப்பட்டது?","options":["நேரிசை வெண்பா","ஆசிரியப்பா","இன்னிசை வெண்பா","குறள் வெண்பா"],"correctAnswer":3,"explanation":"திருக்குறள் இரண்டு அடிகளால் ஆன 'குறள் வெண்பா' என்னும் யாப்பு வடிவத்தில் இயற்றப்பட்டுள்ளது. இதன் முதல் அடியில் நான்கு சீர்களும் இரண்டாம் அடியில் மூன்று சீர்களும் ஆக மொத்தம் ஏழு சீர்கள் அமைந்திருக்கும்.","difficulty":"easy","topic":"திருக்குறள் அமைப்பு"},{"id":405,"subject":"tamil","testNumber":5,"question":"திருக்குறளில் இருமுறை இடம்பெற்றுள்ள ஒரே அதிகாரப் பெயர் எது?","options":["அன்புடைமை","காலமறிதல்","சொல்வன்மை","குறிப்பறிதல்"],"correctAnswer":3,"explanation":"திருக்குறளில் 'குறிப்பறிதல்' என்னும் அதிகாரம் மட்டும் இருமுறை இடம்பெற்றுள்ளது. பொருட்பாலில் 71-ஆம் அதிகாரமாகவும் (அமைச்சியல்), இன்பத்துப்பாலில் 110-ஆம் அதிகாரமாகவும் (களவியல்) இத்தலைப்பு அமைந்துள்ளது.","difficulty":"medium","topic":"திருக்குறள் அமைப்பு"},{"id":406,"subject":"tamil","testNumber":5,"question":"திருக்குறளில் 'உடைமை' என்னும் சொல்லில் முடியும் அதிகாரங்கள் மொத்தம் எத்தனை?","options":["8 அதிகாரங்கள்","9 அதிகாரங்கள்","12 அதிகாரங்கள்","10 அதிகாரங்கள்"],"correctAnswer":3,"explanation":"திருக்குறளில் 'உடைமை' என்னும் சொல்லில் முடியும் அதிகாரங்கள் மொத்தம் பத்து ஆகும். அவை அன்புடைமை, அடக்கமுடைமை, ஒழுக்கமுடைமை, பொறையுடைமை, அருளுடைமை, அறிவுடைமை, ஊக்கமுடைமை, ஆள்வினையுடைமை, பண்புடைமை, நாணுடைமை என்பனவாகும்.","difficulty":"medium","topic":"திருக்குறள் அமைப்பு"},{"id":407,"subject":"tamil","testNumber":5,"question":"திருக்குறள் எந்த எழுத்தில் தொடங்கி, எந்த எழுத்தில் நிறைவடைகிறது?","options":["'அ' எழுத்தில் தொடங்கி 'ன்' எழுத்தில் முடிகிறது","'ஆ' எழுத்தில் தொடங்கி 'ம்' எழுத்தில் முடிகிறது","'அ' எழுத்தில் தொடங்கி 'ம்' எழுத்தில் முடிகிறது","'இ' எழுத்தில் தொடங்கி 'ன்' எழுத்தில் முடிகிறது"],"correctAnswer":0,"explanation":"திருக்குறளின் முதல் குறள் 'அகர முதல எழுத்தெல்லாம்...' எனத் தமிழ் முதல் எழுத்தான 'அ'-வில் தொடங்குகிறது. அதன் 1,330-ஆவது இறுதிக் குறள் '...கூடி முயங்கப் பெறின்' எனத் தமிழ் இறுதி எழுத்தான 'ன்'-இல் நிறைவடைகிறது.","difficulty":"easy","topic":"திருக்குறள் அமைப்பு"},{"id":408,"subject":"tamil","testNumber":5,"question":"திருக்குறளில் இடம்பெற்றுள்ள இரு மலர்களின் பெயர்கள் எவை?","options":["தாமரை, மல்லிகை","கொன்றை, காந்தள்","குறிஞ்சி, முல்லை","அனிச்சம், குவளை"],"correctAnswer":3,"explanation":"திருக்குறளில் அனிச்சம் (குறள் 90, 1111, 1115, 1120) மற்றும் குவளை (குறள் 1114) ஆகிய இரு மலர்களின் பெயர்கள் மட்டுமே இடம்பெற்றுள்ளன. இதேபோல் நெருஞ்சிப்பழம் என்ற ஒரே பழமும் குன்றிமணி என்ற ஒரே விதையும் இடம்பெற்றுள்ளன.","difficulty":"medium","topic":"திருக்குறள் சிறப்புகள்"},{"id":409,"subject":"tamil","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் திருக்குறளின் சிறப்புப் பெயர்களுள் பொருந்தாதது எது?","options":["வாயுறை வாழ்த்து","பொய்யாமொழி","உத்திரவேதம்","குட்டித் தொல்காப்பியம்"],"correctAnswer":3,"explanation":"உலகப் பொதுமறை, முப்பால், வாயுறை வாழ்த்து, பொய்யாமொழி, தெய்வநூல், உத்திரவேதம், தமிழ்மறை ஆகியவை திருக்குறளின் சிறப்புப் பெயர்களாகும். 'குட்டித் தொல்காப்பியம்' என்பது தொன்னூல் விளக்கம் நூலைக் குறிக்கும்; திருக்குறளை அல்ல.","difficulty":"medium","topic":"திருக்குறள் சிறப்புப் பெயர்கள்"},{"id":410,"subject":"tamil","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் திருவள்ளுவருக்கு வழங்கப்படாத சிறப்புப் பெயர் எது?","options":["செந்நாப்போதார்","மாதானுபங்கி","பெருநாவலர்","கவிச்சக்கரவர்த்தி"],"correctAnswer":3,"explanation":"தெய்வப்புலவர், செந்நாப்போதார், பொய்யில் புலவர், பெருநாவலர், முதற்பாவலர், நாயனார், தேவர், மாதானுபங்கி, நான்முகனார் ஆகியவை திருவள்ளுவரின் சிறப்புப் பெயர்களாகும். 'கவிச்சக்கரவர்த்தி' என்பது கம்பருக்கும் ஒட்டக்கூத்தருக்கும் வழங்கப்படும் சிறப்புப் பெயராகும்.","difficulty":"easy","topic":"திருவள்ளுவர் வரலாறு"},{"id":411,"subject":"tamil","testNumber":5,"question":"திருவள்ளுவர் பிறந்த காலமாகத் தமிழ் அறிஞர்களால் கணிக்கப்பட்ட கி.மு. 31-ஆம் ஆண்டின் அடிப்படையில், ஆங்கில ஆண்டு 2025-க்கு இணையான திருவள்ளுவர் ஆண்டு எது?","options":["2054","2061","1994","2056"],"correctAnswer":3,"explanation":"திருவள்ளுவர் பிறந்த ஆண்டு கி.மு. 31 எனக் கணக்கிடப்பட்டுள்ளது. எனவே திருவள்ளுவர் ஆண்டைக் கணக்கிட நடைமுறை ஆங்கில ஆண்டுடன் 31-ஐக் கூட்ட வேண்டும் (2025 + 31 = 2056).","difficulty":"easy","topic":"திருவள்ளுவர் ஆண்டு"},{"id":412,"subject":"tamil","testNumber":5,"question":"திருவள்ளுவர் பிறந்த ஆண்டை கி.மு. 31 என ஆராய்ந்து, 'திருவள்ளுவர் ஆண்டு' முறையை முதன்முதலில் அறிவித்த தமிழ் அறிஞர் யார்?","options":["உ.வே. சாமிநாதையர்","பரிதிமாற்கலைஞர்","திரு.வி. கல்யாணசுந்தரனார்","மறைமலையடிகள்"],"correctAnswer":3,"explanation":"1921-ஆம் ஆண்டு சென்னை பச்சையப்பன் கல்லூரியில் நடைபெற்ற தமிழ் அறிஞர்கள் மாநாட்டில் மறைமலையடிகள் தலைமையில் திருவள்ளுவர் காலம் கி.மு. 31 என முடிவு செய்யப்பட்டு, திருவள்ளுவர் ஆண்டு அறிவிக்கப்பட்டது. இதனைத் தமிழ்நாடு அரசு 1971 முதல் நடைமுறைப்படுத்தியது.","difficulty":"medium","topic":"திருவள்ளுவர் ஆண்டு"},{"id":413,"subject":"tamil","testNumber":5,"question":"தமிழ்நாடு அரசால் 'திருவள்ளுவர் தினம்' ஆண்டுதோறும் எந்த நாளில் கொண்டாடப்படுகிறது?","options":["தை மாதம் முதல் நாள்","வைகாசி விசாகம்","சித்திரை மாதம் முதல் நாள்","தை மாதம் இரண்டாம் நாள்"],"correctAnswer":3,"explanation":"திருவள்ளுவர் ஆண்டு தை மாதம் முதல் நாளில் தொடங்குகிறது. திருவள்ளுவரின் பெருமையைப் போற்றும் வகையில் தமிழ்நாடு அரசு ஆண்டுதோறும் தை மாதம் இரண்டாம் நாளைத் 'திருவள்ளுவர் தினமாக' அறிவித்துக் கொண்டாடுகிறது.","difficulty":"easy","topic":"திருவள்ளுவர் ஆண்டு"},{"id":414,"subject":"tamil","testNumber":5,"question":"கன்னியாகுமரியில் அமைந்துள்ள 133 அடி உயரத் திருவள்ளுவர் சிலையின் 38 அடி உயரப் பீடம் எதை உணர்த்துகிறது?","options":["திருக்குறளின் அறத்துப்பாலில் உள்ள 38 அதிகாரங்கள்","திருக்குறளின் இன்பத்துப்பாலில் உள்ள அதிகாரங்கள்","திருவள்ளுவர் வாழ்ந்த ஆண்டுகள்","திருவள்ளுவமாலையைப் பாடிய புலவர்களின் எண்ணிக்கை"],"correctAnswer":0,"explanation":"கன்னியாகுமரி திருவள்ளுவர் சிலையின் மொத்த உயரம் 133 அடி; இது திருக்குறளின் 133 அதிகாரங்களைக் குறிக்கிறது. அதில் 38 அடி பீடம் அறத்துப்பாலின் 38 அதிகாரங்களையும், 95 அடி சிலை பொருட்பால் (70) மற்றும் இன்பத்துப்பால் (25) ஆகிய 95 அதிகாரங்களையும் உணர்த்துகிறது.","difficulty":"easy","topic":"திருவள்ளுவர் சிலை"},{"id":415,"subject":"tamil","testNumber":5,"question":"கன்னியாகுமரியில் உள்ள திருவள்ளுவர் சிலையை வடிவமைத்த தலைமைச் சிற்பி யார்?","options":["முனைவர் வை. கணபதி ஸ்தபதி","சிற்பி பாலசுப்பிரமணியன்","டி.பி. ராய் சௌத்ரி","முத்தையா ஸ்தபதி"],"correctAnswer":0,"explanation":"கன்னியாகுமரியில் கடல் நடுவே பாறையில் அமைந்துள்ள 133 அடி உயரத் திருவள்ளுவர் சிலையை முனைவர் வை. கணபதி ஸ்தபதி தலைமையிலான சிற்பிகள் வடித்தனர். இச்சிலை 2000-ஆம் ஆண்டு ஜனவரி 1-ஆம் நாள் திறந்து வைக்கப்பட்டது.","difficulty":"easy","topic":"திருவள்ளுவர் சிலை"},{"id":416,"subject":"tamil","testNumber":5,"question":"திருக்குறளின் பெருமையைப் போற்றிப் பாடப்பட்ட 'திருவள்ளுவமாலை' நூலில் உள்ள பாடல்கள் மற்றும் பாடிய புலவர்களின் எண்ணிக்கை எவ்வளவு?","options":["50 பாடல்கள், 50 புலவர்கள்","55 பாடல்கள், 53 புலவர்கள்","53 பாடல்கள், 55 புலவர்கள்","60 பாடல்கள், 54 புலவர்கள்"],"correctAnswer":1,"explanation":"திருக்குறளின் சிறப்பைப் பாராட்டிப் பல்வேறு புலவர்கள் பாடிய பாடல்களின் தொகுப்பு 'திருவள்ளுவமாலை' ஆகும். இதில் 53 புலவர்கள் (அசரீரி உட்பட) பாடிய 55 பாடல்கள் இடம்பெற்றுள்ளன.","difficulty":"medium","topic":"திருவள்ளுவமாலை"},{"id":417,"subject":"tamil","testNumber":5,"question":"\"அணுவைத் துளைத்தேழ் கடலைப் புகட்டிக் குறுகத் தறித்த குறள்\" என்று திருக்குறளைப் போற்றிப் பாடியவர் யார்?","options":["ஔவையார்","இடைக்காடனார்","கபிலர்","மாங்குடி மருதனார்"],"correctAnswer":0,"explanation":"திருக்குறளின் செறிவான கருத்து ஆழத்தைப் பாராட்டி \"அணுவைத் துளைத்தேழ் கடலைப் புகட்டிக் குறுகத் தறித்த குறள்\" என்று ஔவையார் பாடியுள்ளார். இதேபோல் \"கடுகைத் துளைத்தேழ் கடலைப் புகட்டிக் குறுகத் தறித்த குறள்\" என இடைக்காடனார் பாடியுள்ளார்.","difficulty":"medium","topic":"திருவள்ளுவமாலை"},{"id":418,"subject":"tamil","testNumber":5,"question":"\"தினையளவு போதாச் சிறுபுல்நீர் நீண்ட / பனையளவு காட்டும் படித்தால்\" எனத் திருவள்ளுவமாலையில் பாடிய சங்கப் புலவர் யார்?","options":["கபிலர்","நக்கீரர்","பரணர்","கல்லாடர்"],"correctAnswer":0,"explanation":"சிறிய புல்லின் நுனியில் உள்ள தினை அளவு கூட இல்லாத பனித்துளி நெடிய பனைமரத்தின் முழு உருவத்தையும் காட்டுவதுபோல, சிறிய குறட்பாக்கள் மிகப் பெரிய வாழ்வியல் உண்மைகளைக் காட்டுகின்றன எனக் கபிலர் திருவள்ளுவமாலையில் பாடியுள்ளார்.","difficulty":"hard","topic":"திருவள்ளுவமாலை"},{"id":419,"subject":"tamil","testNumber":5,"question":"\"வள்ளுவனைப் பெற்றதால் பெற்றதே புகழ் வையகமே\" என்று திருவள்ளுவரைப் போற்றிப் பாடிய கவிஞர் யார்?","options":["மகாகவி பாரதியார்","பாவேந்தர் பாரதிதாசன்","நாமக்கல் கவிஞர் வெ. இராமலிங்கனார்","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":1,"explanation":"\"வள்ளுவனைப் பெற்றதால் பெற்றதே புகழ் வையகமே\" என்றும், \"இணையிலை முப்பாலுக்கு இந்நிலத்தே\" என்றும் பாவேந்தர் பாரதிதாசன் திருவள்ளுவரையும் திருக்குறளையும் போற்றியுள்ளார். \"வள்ளுவன் தன்னை உலகினுக்கே தந்து வான்புகழ் கொண்ட தமிழ்நாடு\" என்பது பாரதியாரின் புகழ்பெற்ற பாடலடியாகும்.","difficulty":"easy","topic":"திருவள்ளுவர் புகழ்"},{"id":420,"subject":"tamil","testNumber":5,"question":"திருக்குறளுக்கு உரை எழுதிய பழைய உரையாசிரியர்கள் பதின்மருள் காலத்தால் முந்தியவர் யார்?","options":["பரிமேலழகர்","மணக்குடவர்","காளிங்கர்","பரிதியார்"],"correctAnswer":1,"explanation":"தருமர், மணக்குடவர், தாமத்தர், நச்சர், பரிதி, பரிமேலழகர், திருமலையர், மல்லர், பரிப்பெருமாள், காளிங்கர் ஆகிய பதின்மர் திருக்குறளுக்குப் பழைய உரை எழுதியுள்ளனர். இவர்களுள் காலத்தால் முந்திய உரை மணக்குடவர் உரையாகும்.","difficulty":"medium","topic":"திருக்குறள் உரையாசிரியர்கள்"},{"id":421,"subject":"tamil","testNumber":5,"question":"திருக்குறள் பழைய உரைகளுள் மிகச் சிறந்த உரையாக அறிஞர்களால் போற்றப்படுவது எது?","options":["பரிப்பெருமாள் உரை","காளிங்கர் உரை","பரிமேலழகர் உரை","பரிதியார் உரை"],"correctAnswer":2,"explanation":"திருக்குறளுக்கு நமக்குக் கிடைத்துள்ள ஐந்து பழைய உரைகளுள் (மணக்குடவர், பரிமேலழகர், பரிதியார், பரிப்பெருமாள், காளிங்கர்) பரிமேலழகர் எழுதிய உரையே இலக்கண நுட்பமும் தர்க்கத் தெளிவும் கொண்ட மிகச் சிறந்த உரையாகப் போற்றப்படுகிறது.","difficulty":"easy","topic":"திருக்குறள் உரையாசிரியர்கள்"},{"id":422,"subject":"tamil","testNumber":5,"question":"திருக்குறள் முதன்முதலில் எந்த ஆண்டு, யாரால் அச்சிடப்பட்டு வெளியிடப்பட்டது?","options":["1812 – தஞ்சை ஞானப்பிரகாசர்","1835 – ஆறுமுக நாவலர்","1861 – சி.வை. தாமோதரனார்","1886 – உ.வே. சாமிநாதையர்"],"correctAnswer":0,"explanation":"ஓலைச்சுவடிகளில் இருந்த திருக்குறள் முதன்முதலில் 1812-ஆம் ஆண்டு தஞ்சாவூரில் மலையத்துவசன் மகன் தஞ்சை ஞானப்பிரகாசர் என்பவரால் அச்சிடப்பட்டு வெளியிடப்பட்டது.","difficulty":"medium","topic":"திருக்குறள் பதிப்பு வரலாறு"},{"id":423,"subject":"tamil","testNumber":5,"question":"திருக்குறளின் அறத்துப்பால் மற்றும் பொருட்பாலை முதன்முதலில் இலத்தீன் மொழியில் மொழிபெயர்த்தவர் யார்?","options":["ஜி.யு. போப்","கால்டுவெல்","வீரமாமுனிவர்","கார்ல் கிரௌல்"],"correctAnswer":2,"explanation":"இத்தாலிய அறிஞரான வீரமாமுனிவர் (கான்ஸ்டான்டின் ஜோசப் பெஸ்கி) 1730-ஆம் ஆண்டில் திருக்குறளின் அறத்துப்பாலையும் பொருட்பாலையும் இலத்தீன் மொழியில் மொழிபெயர்த்து ஐரோப்பியர்களுக்குத் திருக்குறளின் பெருமையை அறிமுகப்படுத்தினார்.","difficulty":"medium","topic":"திருக்குறள் மொழிபெயர்ப்புகள்"},{"id":424,"subject":"tamil","testNumber":5,"question":"திருக்குறள் முழுவதையும் 1886-ஆம் ஆண்டு ஆங்கிலத்தில் மொழிபெயர்த்து வெளியிட்டவர் யார்?","options":["பிரான்சிஸ் ஒயிட் எல்லிஸ்","ஜி.யு. போப்","வ.வே.சு. ஐயர்","இராபர்ட் கால்டுவெல்"],"correctAnswer":1,"explanation":"தமிழுக்குப் பெரும் தொண்டாற்றிய ஜி.யு. போப் 1886-ஆம் ஆண்டு திருக்குறள் முழுவதையும் 'The Sacred Kurral' என்ற பெயரில் ஆங்கிலத்தில் மொழிபெயர்த்து வெளியிட்டார்.","difficulty":"easy","topic":"திருக்குறள் மொழிபெயர்ப்புகள்"},{"id":425,"subject":"tamil","testNumber":5,"question":"திருவள்ளுவரின் உருவம் பொறித்த தங்க நாணயத்தை வெளியிட்டுப் பெருமை சேர்த்த சென்னை மாகாண ஆட்சியர் யார்?","options":["பிரான்சிஸ் ஒயிட் எல்லிஸ்","தாமஸ் மன்றோ","வில்லியம் பென்டிங்க்","டபிள்யு.எச். ட்ரூ"],"correctAnswer":0,"explanation":"சென்னை மாகாண ஆட்சியராகவும் தமிழ்ப் பற்றாளராகவும் விளங்கிய பிரான்சிஸ் ஒயிட் எல்லிஸ் (F.W. Ellis) திருக்குறளின் அறத்துப்பால் பகுதிகளுக்கு ஆங்கில உரை எழுதியதோடு, திருவள்ளுவர் உருவம் பொறித்த தங்க நாணயத்தையும் வெளியிட்டார்.","difficulty":"hard","topic":"திருக்குறள் மொழிபெயர்ப்புகள்"},{"id":426,"subject":"tamil","testNumber":5,"question":"\"கோளில் பொறியின் குணமிலவே எண்குணத்தான் / தாளை வணங்காத் தலை\" — இக்குறளில் 'எண்குணத்தான்' என்பது யாரைக் குறிக்கிறது?","options":["அரசன்","துறவி","இறைவன்","ஆசிரியர்"],"correctAnswer":2,"explanation":"கடவுள் வாழ்த்து அதிகாரத்தில் (குறள் 9) இடம்பெறும் இக்குறளில் 'எண்குணத்தான்' என்பது எட்டு நற்குணங்களை உடைய இறைவனைக் குறிக்கும். கேளாத செவி, காணாத கண் முதலிய புலனில்லாத ஐம்பொறிகள் போல இறைவனின் திருவடிகளை வணங்காத தலையும் பயனற்றது என்பது இக்குறளின் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – கடவுள் வாழ்த்து"},{"id":427,"subject":"tamil","testNumber":5,"question":"\"வேண்டுதல் வேண்டாமை இலானடி சேர்ந்தார்க்கு / யாண்டும் இடும்பை இல\" — இக்குறளில் 'இடும்பை' என்பதன் பொருள் என்ன?","options":["செல்வம்","துன்பம்","அச்சம்","வறுமை"],"correctAnswer":1,"explanation":"கடவுள் வாழ்த்து அதிகாரத்தின் நான்காம் குறளில் உள்ள 'இடும்பை' என்பதற்குத் 'துன்பம்' என்பது பொருளாகும். விருப்பு வெறுப்பு இல்லாத இறைவனின் திருவடிகளைப் பொருந்தி நினைப்பவர்களுக்கு எக்காலத்திலும் எவ்விடத்திலும் துன்பம் இல்லை என்பது இக்குறளின் கருத்தாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – கடவுள் வாழ்த்து"},{"id":428,"subject":"tamil","testNumber":5,"question":"\"விண்ணின்று பொய்ப்பின் விரிநீர் வியனுலகத்து / உள்நின்று உடற்றும் பசி\" — இக்குறளில் 'வியனுலகம்' என்பதன் பொருள் யாது?","options":["வானுலகம்","சிறிய உலகம்","பரந்த உலகம்","தெய்வ உலகம்"],"correctAnswer":2,"explanation":"வான்சிறப்பு அதிகாரத்தில் (குறள் 13) இடம்பெறும் 'வியனுலகம்' என்பதில் 'வியன்' என்பது அகன்ற, பரந்த என்ற பொருளைத் தரும் உரிச்சொல்லாகும். மழை உரிய காலத்தில் பெய்யாமல் பொய்த்தால், கடல் சூழ்ந்த பரந்த இவ்வுலகில் பசி நிலைத்து நின்று உயிர்களை வருத்தும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – வான்சிறப்பு"},{"id":429,"subject":"tamil","testNumber":5,"question":"\"தானம் தவம்இரண்டும் தங்கா வியனுலகம் / _______\" — இக்குறளின் இரண்டாம் அடியைச் சரியாக நிரப்புக.","options":["வான்நின்று பொய்த்த தெனின்","வானம் வழங்கா தெனின்","மழையது பெய்யா தெனின்","நீரின்றி வாழா தெனின்"],"correctAnswer":1,"explanation":"வான்சிறப்பு அதிகாரத்தின் 19-ஆம் குறள்: \"தானம் தவம்இரண்டும் தங்கா வியனுலகம் / வானம் வழங்கா தெனின்\". வானம் மழையைப் பொழியாவிட்டால் இப்பரந்த உலகில் பிறருக்கு வழங்கும் தானமும் தமக்காகச் செய்யும் தவமும் ஆகிய இரண்டும் நிலைபெறாது என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – வான்சிறப்பு"},{"id":430,"subject":"tamil","testNumber":5,"question":"\"நிறைமொழி மாந்தர் பெருமை நிலத்து / மறைமொழி காட்டி விடும்\" — இக்குறள் இடம்பெற்றுள்ள அதிகாரம் எது?","options":["அறன் வலியுறுத்தல்","நீத்தார் பெருமை","வாய்மை","பெரியாரைத் துணைக்கோடல்"],"correctAnswer":1,"explanation":"இக்குறள் அறத்துப்பாலில் பாயிரவியலின் மூன்றாம் அதிகாரமான 'நீத்தார் பெருமை'யில் (குறள் 28) அமைந்துள்ளது. பயன் நிறைந்த மொழிகளைக் கூறும் துறவிகளாகிய பெரியோர்களின் பெருமையை, உலகில் அவர்கள் அருளிய மந்திரச் சொற்களே (மறைமொழி) காட்டிவிடும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – நீத்தார் பெருமை"},{"id":431,"subject":"tamil","testNumber":5,"question":"\"குணமென்னும் குன்றேறி நின்றார் வெகுளி / கணமேயும் காத்தல் அரிது\" — இக்குறளில் பயின்று வரும் அணி எது?","options":["உவமையணி","உருவக அணி","பிறிது மொழிதல் அணி","சொற்பொருள் பின்வருநிலையணி"],"correctAnswer":1,"explanation":"நீத்தார் பெருமை அதிகாரத்தில் உள்ள இக்குறளில் (குறள் 29) நற்குணத்தைக் குன்றாக ('குணமென்னும் குன்று') உருவகித்துக் கூறியுள்ளதால் இது உருவக அணியாகும். நற்குணமாகிய மலையின் மீது ஏறி நின்ற துறவியர் கொள்ளும் சினம் ஒரு கணம் என்றாலும் அதிலிருந்து தப்பித்தல் அரிது என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – நீத்தார் பெருமை"},{"id":432,"subject":"tamil","testNumber":5,"question":"\"மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன் / ஆகுல நீர பிற\" — இக்குறளில் 'ஆகுல நீர' என்பதன் பொருள் என்ன?","options":["அமைதித் தன்மை உடையன","ஆரவாரத் தன்மை உடையன","அறத்தின் அடிப்படை ஆனவை","அருள் தன்மை உடையன"],"correctAnswer":1,"explanation":"அறன் வலியுறுத்தல் அதிகாரத்தின் 34-ஆம் குறளில் 'ஆகுலம்' என்றால் ஆரவாரம் என்று பொருள். மனத்தில் குற்றமில்லாமல் தூய்மையாக இருப்பதே முழுமையான அறமாகும்; அதனை விடுத்துச் செய்யும் மற்றவை அனைத்தும் வெறும் ஆரவாரத் தன்மை உடையனவே ஆகும்.","difficulty":"hard","topic":"அறத்துப்பால் – அறன் வலியுறுத்தல்"},{"id":433,"subject":"tamil","testNumber":5,"question":"\"அழுக்காறு அவாவெகுளி இன்னாச்சொல் நான்கும் / இழுக்கா இயன்றது அறம்\" — இக்குறளில் 'அழுக்காறு' என்பதன் பொருள் யாது?","options":["பேராசை","சினம்","பொறாமை","கடுஞ்சொல்"],"correctAnswer":2,"explanation":"அறன் வலியுறுத்தல் அதிகாரத்தின் 35-ஆம் குறளில் 'அழுக்காறு' என்பது பொறாமையையும், 'அவா' என்பது பேராசையையும், 'வெகுளி' என்பது சினத்தையும், 'இன்னாச்சொல்' என்பது கடுஞ்சொல்லையும் குறிக்கும். இந்நான்கு குற்றங்களையும் விலக்கி நடப்பதே அறமாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – அறன் வலியுறுத்தல்"},{"id":434,"subject":"tamil","testNumber":5,"question":"\"அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை / _______\" — விடுபட்ட குறள் அடியைத் தேர்ந்தெடுக்கவும்.","options":["நன்றும் பயனும் அது","பண்பும் பயனும் அது","இன்பும் அறனும் அது","சிறப்பும் பயனும் அது"],"correctAnswer":1,"explanation":"இல்வாழ்க்கை அதிகாரத்தின் 45-ஆம் குறள்: \"அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை / பண்பும் பயனும் அது\". அன்பையும் அறத்தையும் கொண்டதாக இல்வாழ்க்கை விளங்கினால், அவ்வாழ்க்கையின் பண்பும் பயனும் அதுவே ஆகும் என்பது இதன் பொருளாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – இல்வாழ்க்கை"},{"id":435,"subject":"tamil","testNumber":5,"question":"\"வையத்துள் வாழ்வாங்கு வாழ்பவன் வானுறையும் / தெய்வத்துள் வைக்கப் படும்\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["அன்புடைமை","இல்வாழ்க்கை","ஒழுக்கமுடைமை","சான்றாண்மை"],"correctAnswer":1,"explanation":"இக்குறள் அறத்துப்பால் இல்லறவியலில் உள்ள 'இல்வாழ்க்கை' அதிகாரத்தின் இறுதிக் குறளாகும் (குறள் 50). உலகத்தில் வாழ வேண்டிய அறநெறிப்படி இல்வாழ்க்கை வாழ்பவன், வானுலகில் வாழும் தெய்வத்திற்கு இணையாக வைத்து மதிக்கப்படுவான் என்பது இதன் பொருளாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – இல்வாழ்க்கை"},{"id":436,"subject":"tamil","testNumber":5,"question":"\"மோப்பக் குழையும் அனிச்சம் முகந்திரிந்து / நோக்கக் குழையும் விருந்து\" — இக்குறளில் அனிச்ச மலரோடு ஒப்பிடப்படுவது எது?","options":["இனிய சொல்","விருந்தினர் உள்ளம்","நல்ல நட்பு","கல்வி அறிவு"],"correctAnswer":1,"explanation":"விருந்தோம்பல் அதிகாரத்தின் 90-ஆம் குறளில் அனிச்ச மலர் முகர்ந்து பார்த்த அளவிலேயே வாடிவிடும்; ஆனால் வீட்டுக்கு வந்த விருந்தினர் நம் முகம் சற்று மாறுபட்டுப் பார்த்த அளவிலேயே மனம் வாடிவிடுவர் என விருந்தினரின் மென்மையான உள்ளத்தைத் திருவள்ளுவர் உணர்த்துகிறார்.","difficulty":"easy","topic":"அறத்துப்பால் – விருந்தோம்பல்"},{"id":437,"subject":"tamil","testNumber":5,"question":"\"செல்விருந்து ஓம்பி வருவிருந்து பார்த்திருப்பான் / நல்விருந்து வானத் தவர்க்கு\" — இக்குறளில் 'வானத்தவர்' என்பது யாரைக் குறிக்கிறது?","options":["அரசர்கள்","தேவர்கள்","துறவிகள்","வணிகர்கள்"],"correctAnswer":1,"explanation":"விருந்தோம்பல் அதிகாரத்தின் 86-ஆம் குறளில் 'வானத்தவர்' என்பது வானுலகில் வாழும் தேவர்களைக் குறிக்கும். வந்த விருந்தினரைப் போற்றி வழியனுப்பி, மேலும் வரும் விருந்தினரை எதிர்பார்த்துக் காத்திருப்பவன் வானுலகத் தேவர்களுக்கும் நல்ல விருந்தினனாகப் போற்றப்படுவான் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – விருந்தோம்பல்"},{"id":438,"subject":"tamil","testNumber":5,"question":"\"இனிய உளவாக இன்னாத கூறல் / கனியிருப்பக் காய்கவர்ந் தற்று\" — இக்குறளில் பயின்று வரும் அணி எது?","options":["வேற்றுமை அணி","உருவக அணி","உவமையணி","தற்குறிப்பேற்ற அணி"],"correctAnswer":2,"explanation":"இனியவை கூறல் அதிகாரத்தின் 100-ஆம் குறளில் 'அற்று' என்னும் உவம உருபு வெளிப்படையாக வந்துள்ளதால் இது உவமையணியாகும். இனிய சொற்கள் இருக்கும்போது கடுஞ்சொற்களைப் பேசுவது, நன்கு பழுத்த கனி இருக்கும்போது காயை உண்ண விரும்புவதைப் போன்றது என்பது இதன் பொருளாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – இனியவை கூறல்"},{"id":439,"subject":"tamil","testNumber":5,"question":"இனியவை கூறல் அதிகாரத்தின்படி, ஒருவனுக்கு உண்மையான அணிகலன்கள் (ஆபரணங்கள்) எவை?","options":["பொன்னும் மணியும்","பணிவும் இன்சொல்லும்","செல்வமும் புகழும்","வீரமும் கொடையும்"],"correctAnswer":1,"explanation":"\"பணிவுடையன் இன்சொலன் ஆதல் ஒருவற்கு / அணியல்ல மற்றுப் பிற\" (குறள் 95) என்பதற்கேற்ப, பணிவு உடையவனாகவும் இனிய சொற்களைப் பேசுபவனாகவும் இருப்பதே ஒருவனுக்குச் சிறந்த அணிகலன்கள் ஆகும்; மற்ற அணிகலன்கள் உண்மையான அணிகள் அல்ல என்பது வள்ளுவர் கருத்தாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – இனியவை கூறல்"},{"id":440,"subject":"tamil","testNumber":5,"question":"\"காலத்தி னால்செய்த நன்றி சிறிதெனினும் / ஞாலத்தின் மாணப் பெரிது\" — இக்குறளில் 'ஞாலம்' என்பதன் பொருள் என்ன?","options":["வானம்","கடல்","உலகம்","மலை"],"correctAnswer":2,"explanation":"செய்ந்நன்றி அறிதல் அதிகாரத்தின் 102-ஆம் குறளில் 'ஞாலம்' என்பது உலகத்தைக் குறிக்கும். தக்க காலத்தில் ஒருவர் செய்த உதவி அளவால் சிறியதாக இருந்தாலும், அதன் மதிப்பு இந்த உலகத்தை விடவும் மிகப் பெரியதாகும் என்பது இக்குறளின் பொருளாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – செய்ந்நன்றி அறிதல்"},{"id":441,"subject":"tamil","testNumber":5,"question":"\"எந்நன்றி கொன்றார்க்கும் உய்வுண்டாம் உய்வில்லை / செய்ந்நன்றி கொன்ற மகற்கு\" — இக்குறளின்படி எத்தகைய குற்றம் செய்தவருக்கு விமோசனம் (உய்வு) இல்லை?","options":["பொய் சொல்பவருக்கு","பிறர் செய்த உதவியை மறந்தவருக்கு","கல்வி கற்காதவருக்கு","விருந்தினரைப் போற்றாதவருக்கு"],"correctAnswer":1,"explanation":"செய்ந்நன்றி அறிதல் அதிகாரத்தின் 110-ஆம் குறளில், எந்த அறத்தை அழித்தவருக்கும் தப்பிப் பிழைக்க வழி உண்டு; ஆனால் பிறர் செய்த உதவியை மறந்து அழித்தவருக்கு ஒருபோதும் உய்வு (விமோசனம்) இல்லை எனத் திருவள்ளுவர் வலியுறுத்துகிறார்.","difficulty":"easy","topic":"அறத்துப்பால் – செய்ந்நன்றி அறிதல்"},{"id":442,"subject":"tamil","testNumber":5,"question":"\"ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின் / எழுமையும் ஏமாப்பு உடைத்து\" — இக்குறளில் ஐம்புலன்களை அடக்குவதற்குத் திருவள்ளுவர் எதனை உவமையாகக் கூறுகிறார்?","options":["யானை","ஆமை","மயில்","புலி"],"correctAnswer":1,"explanation":"அடக்கமுடைமை அதிகாரத்தின் 126-ஆம் குறளில் ஆமை தன் ஐந்து உறுப்புகளையும் ஓட்டிற்குள் இழுத்து அடக்கிக் கொள்வதுபோல, மனிதன் ஒரு பிறவியில் ஐம்புலன்களையும் அடக்கினால் அது ஏழு பிறவிகளுக்கும் பாதுகாப்பாக அமையும் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"medium","topic":"அறத்துப்பால் – அடக்கமுடைமை"},{"id":443,"subject":"tamil","testNumber":5,"question":"\"ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின் / எழுமையும் ஏமாப் புடைத்து\" — இக்குறளில் 'ஏமாப்பு' என்பதன் பொருள் யாது?","options":["துன்பம்","ஏமாற்றம்","பாதுகாப்பு","செல்வம்"],"correctAnswer":2,"explanation":"அடக்கமுடைமை அதிகாரத்தின் 126-ஆம் குறளில் 'ஏமாப்பு' என்பது 'பாதுகாப்பு' என்ற பொருளைத் தரும். ஒரு பிறவியில் ஆமை தன் ஐந்து உறுப்புகளையும் ஓட்டிற்குள் அடக்கிக் கொள்வதுபோல் ஐம்பொறிகளையும் அடக்கி வாழ்ந்தால், அது ஏழு பிறவிகளுக்கும் பாதுகாப்பைத் தரும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – அடக்கமுடைமை"},{"id":444,"subject":"tamil","testNumber":5,"question":"\"ஒழுக்கம் விழுப்பம் தரலான் ஒழுக்கம் / உயிரினும் ஓம்பப் படும்\" — இக்குறளில் 'விழுப்பம்' என்பதன் பொருள் என்ன?","options":["வறுமை","சிறப்பு","இளமை","வலிமை"],"correctAnswer":1,"explanation":"ஒழுக்கமுடைமை அதிகாரத்தின் முதல் குறளான இதில் (குறள் 131) 'விழுப்பம்' என்பது 'சிறப்பு' அல்லது 'மேன்மை' என்று பொருள்படும். ஒழுக்கம் அனைவருக்கும் மேன்மையைத் தருவதால் அவ்வொழுக்கத்தை உயிரை விடவும் மேலாகப் போற்றிக் காக்க வேண்டும்.","difficulty":"easy","topic":"அறத்துப்பால் – ஒழுக்கமுடைமை"},{"id":445,"subject":"tamil","testNumber":5,"question":"\"உலகத்தோடு ஒட்ட ஒழுகல் பலகற்றும் / கல்லார் அறிவிலா தார்\" — இக்குறளின் சரியான பொருள் எது?","options":["பல நூல்களைக் கற்றவரே உலகத்தை ஆள்வார்","உலக நடைமுறைக்கு ஏற்ப வாழத் தெரியாதவர் பல நூல்களைக் கற்றாலும் அறிவில்லாதவரே","கல்வி கற்காதவர்கள் உலகத்தை விட்டு விலக வேண்டும்","அறிவுடையோர் மட்டுமே பல நூல்களை எழுத இயலும்"],"correctAnswer":1,"explanation":"ஒழுக்கமுடைமை அதிகாரத்தின் 140-ஆம் குறளில், உலகத்தோடு பொருந்தி வாழும் ஒழுக்கத்தை அறியாதவர்கள் எத்தனை நூல்களைப் படித்திருந்தாலும் அவர்கள் கல்லாத அறிவற்றவர்களாகவே கருதப்படுவர் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"medium","topic":"அறத்துப்பால் – ஒழுக்கமுடைமை"},{"id":446,"subject":"tamil","testNumber":5,"question":"\"அகழ்வாரைத் தாங்கும் நிலம்போலத் தம்மை / இகழ்வார்ப் பொறுத்தல் தலை\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["அடக்கமுடைமை","பொறையுடைமை","வெகுளாமை","பண்புடைமை"],"correctAnswer":1,"explanation":"இக்குறள் அறத்துப்பால் இல்லறவியலில் உள்ள 'பொறையுடைமை' அதிகாரத்தின் முதல் குறளாகும் (குறள் 151). தன்னைத் தோண்டுபவரைத் தாங்கிக்கொள்ளும் நிலத்தைப்போல, தம்மை இகழ்ந்து பேசுபவரையும் பொறுத்துக் கொள்வதே தலையாய பண்பாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – பொறையுடைமை"},{"id":447,"subject":"tamil","testNumber":5,"question":"\"மிகுதியான் மிக்கவை செய்தாரைத் தாம்தம் / தகுதியான் வென்று விடல்\" — இக்குறளில் தீமை செய்தவரை எதனால் வெல்ல வேண்டும் என வள்ளுவர் கூறுகிறார்?","options":["சினத்தால்","படை வலிமையால்","பொறுமை என்னும் தகுதியால்","செல்வத்தின் மிகுதியால்"],"correctAnswer":2,"explanation":"பொறையுடைமை அதிகாரத்தின் 158-ஆம் குறளில், செருக்கினால் தமக்குத் தீய செயல்களைச் செய்தவர்களைத் தம்முடைய பொறுமை என்னும் நற்பண்பால் வென்றுவிட வேண்டும் எனத் திருவள்ளுவர் அறிவுறுத்துகிறார்.","difficulty":"medium","topic":"அறத்துப்பால் – பொறையுடைமை"},{"id":448,"subject":"tamil","testNumber":5,"question":"\"கண்ணின்று கண்ணறச் சொல்லினும் சொல்லற்க / முன்னின்று பின்னோக்காச் சொல்\" — இக்குறள் எதைத் தவிர்க்க வேண்டும் என்று வலியுறுத்துகிறது?","options":["வஞ்சனை செய்தல்","புறங்கூறுதல்","கள்ளுண்ணுதல்","சூதாடுதல்"],"correctAnswer":1,"explanation":"புறங்கூறாமை அதிகாரத்தின் 184-ஆம் குறள் இது. ஒருவர் எதிரே நின்று இரக்கமற்ற கடுஞ்சொற்களைக் கூறினாலும் கூறலாம்; ஆனால் அவர் இல்லாதபோது அவரைப் பற்றிப் பின்விளைவுகளை நோக்காமல் புறங்கூறுதல் கூடாது என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – புறங்கூறாமை"},{"id":449,"subject":"tamil","testNumber":5,"question":"\"ஏதிலார் குற்றம்போல் தங்குற்றம் காண்கிற்பின் / தீதுண்டோ மன்னும் உயிர்க்கு\" — இக்குறளில் 'ஏதிலார்' என்பதன் பொருள் யாது?","options":["உறவினர்","அயலார் (பிறர்)","நண்பர்கள்","சான்றோர்"],"correctAnswer":1,"explanation":"புறங்கூறாமை அதிகாரத்தின் 190-ஆம் குறளில் 'ஏதிலார்' என்பது அயலார் அல்லது பிறர் எனப் பொருள்படும். பிறருடைய குற்றத்தைக் காண்பது போலத் தன்னுடைய குற்றத்தையும் ஆராய்ந்து காண வல்லவர்க்கு வாழ்வில் எந்தத் தீங்கும் நேராது என்பது இதன் பொருளாகும்.","difficulty":"hard","topic":"அறத்துப்பால் – புறங்கூறாமை"},{"id":450,"subject":"tamil","testNumber":5,"question":"\"வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம் / _______\" — இக்குறளின் இரண்டாம் அடியை நிரப்புக.","options":["குறியெதிர்ப்பை நீர துடைத்து","பயனெதிர்ப்பை நீர துடைத்து","நன்றியெதிர்ப்பை நீர துடைத்து","பொருளெதிர்ப்பை நீர துடைத்து"],"correctAnswer":0,"explanation":"ஈகை அதிகாரத்தின் முதல் குறள் (குறள் 221): \"வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம் / குறியெதிர்ப்பை நீர துடைத்து\". வறியவர்களுக்கு ஒரு பொருளைக் கொடுப்பதே உண்மையான ஈகையாகும்; மற்றவர்களுக்குக் கொடுப்பதெல்லாம் கைம்மாறு எதிர்பார்த்துக் கொடுக்கும் தன்மை உடையது.","difficulty":"hard","topic":"அறத்துப்பால் – ஈகை"},{"id":451,"subject":"tamil","testNumber":5,"question":"\"வாய்மை எனப்படுவது யாதெனின் யாதொன்றும் / தீமை இலாத சொலல்\" — இக்குறளின்படி திருவள்ளுவர் கூறும் வாய்மையின் இலக்கணம் யாது?","options":["எப்போதும் உண்மை மட்டுமே பேசுதல்","சான்றோருக்கு ஏற்புடைய சொற்களைக் கூறுதல்","பிறருக்குச் சிறிதும் தீமை தராத சொற்களைக் கூறுதல்","இனிய ஓசையுடைய சொற்களைத் தேர்ந்து பேசுதல்"],"correctAnswer":2,"explanation":"வாய்மை அதிகாரத்தின் முதல் குறள் (குறள் 291) இது. வாய்மை எனப்படுவது யாது என்றால், பிற உயிர்களுக்குச் சிறிதளவும் தீங்கு விளைவிக்காத சொற்களைப் பேசுதலே ஆகும் எனத் திருவள்ளுவர் வாய்மைக்கு உயரிய இலக்கணம் வகுக்கிறார்.","difficulty":"easy","topic":"அறத்துப்பால் – வாய்மை"},{"id":452,"subject":"tamil","testNumber":5,"question":"\"புறந்தூய்மை நீரான் அமையும் அகந்தூய்மை / _______\" — இக்குறளின் இரண்டாம் அடியைச் சரியாக நிறைவு செய்க.","options":["அன்பினால் காணப் படும்","தவத்தினால் காணப் படும்","அருளினால் காணப் படும்","வாய்மையால் காணப் படும்"],"correctAnswer":3,"explanation":"வாய்மை அதிகாரத்தின் 298-ஆம் குறள்: \"புறந்தூய்மை நீரான் அமையும் அகந்தூய்மை / வாய்மையால் காணப் படும்\". உடலின் புறத்தூய்மை நீரால் உண்டாகும்; உள்ளத்தின் அகத்தூய்மை வாய்மையால் (உண்மை பேசுதலால்) வெளிப்படும் என்பது இதன் பொருளாகும்.","difficulty":"easy","topic":"அறத்துப்பால் – வாய்மை"},{"id":453,"subject":"tamil","testNumber":5,"question":"\"தன்னைத்தான் காக்கின் சினங்காக்க காவாக்கால் / தன்னையே கொல்லும் சினம்\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["வெகுளாமை","அடக்கமுடைமை","கொல்லாமை","பொறையுடைமை"],"correctAnswer":0,"explanation":"இக்குறள் அறத்துப்பால் துறவறவியலில் உள்ள 'வெகுளாமை' அதிகாரத்தில் (குறள் 305) அமைந்துள்ளது. ஒருவன் தன்னைத்தானே துன்பத்திலிருந்து காத்துக் கொள்ள விரும்பினால் சினம் வராமல் காக்க வேண்டும்; அவ்வாறு காக்காவிட்டால் அந்தச் சினமே அவனை அழித்துவிடும்.","difficulty":"easy","topic":"அறத்துப்பால் – வெகுளாமை"},{"id":454,"subject":"tamil","testNumber":5,"question":"\"பகுத்துண்டு பல்லுயிர் ஓம்புதல் நூலோர் / தொகுத்தவற்றுள் எல்லாம் தலை\" — இக்குறள் எந்த அதிகாரத்தில் இடம்பெற்றுள்ளது?","options":["ஈகை","விருந்தோம்பல்","அருளுடைமை","கொல்லாமை"],"correctAnswer":3,"explanation":"இக்குறள் அறத்துப்பால் துறவறவியலில் உள்ள 'கொல்லாமை' அதிகாரத்தின் இரண்டாம் குறளாகும் (குறள் 322). தம்மிடம் உள்ளதைப் பிற உயிர்களோடு பகிர்ந்து உண்டு பல உயிர்களையும் பாதுகாத்தலே அறநூலார் தொகுத்துக் கூறிய அறங்களுள் தலையாயது என்பது இதன் பொருளாகும்.","difficulty":"hard","topic":"அறத்துப்பால் – கொல்லாமை"},{"id":455,"subject":"tamil","testNumber":5,"question":"\"ஊழிற் பெருவலி யாவுள மற்றொன்று / சூழினும் தான்முந் துறும்\" — அறத்துப்பாலின் இறுதி அதிகாரமான 'ஊழ்' எந்த இயலில் இடம்பெற்றுள்ளது?","options":["பாயிரவியல்","இல்லறவியல்","துறவறவியல்","ஊழியல்"],"correctAnswer":3,"explanation":"அறத்துப்பாலின் 38-ஆவது மற்றும் இறுதி அதிகாரமான 'ஊழ்', தனியொரு இயலான 'ஊழியல்' என்னும் இயலில் இடம்பெற்றுள்ளது. ஊழைவிட மிகுந்த வலிமை உடையது வேறு எதுவுமில்லை; ஊழை வெல்ல வேறு வழியை எண்ணினாலும் அந்த வழியிலும் ஊழே முந்தி வந்து நிற்கும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"அறத்துப்பால் – ஊழ்"},{"id":456,"subject":"tamil","testNumber":5,"question":"\"கற்க கசடறக் கற்பவை கற்றபின் / நிற்க அதற்குத் தக\" — இக்குறளில் 'கசடற' என்பதன் பொருள் யாது?","options":["குற்றமற (பிழையின்றி)","விரைவாக","முழுமையாக மனப்பாடம் செய்து","பிறர் அறியாமல்"],"correctAnswer":0,"explanation":"பொருட்பாலின் 'கல்வி' அதிகாரத்தின் முதல் குறள் (குறள் 391) இது. இதில் 'கசடு' என்றால் குற்றம் அல்லது பிழை; 'கசடற' என்றால் குற்றமற (ஐயமின்றித் தெளிவாக) என்று பொருள். கற்கத் தகுந்த நூல்களைக் குற்றமறக் கற்று, கற்ற நெறிப்படி வாழ்க்கையில் நடக்க வேண்டும்.","difficulty":"easy","topic":"பொருட்பால் – கல்வி"},{"id":457,"subject":"tamil","testNumber":5,"question":"\"தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக் / கற்றனைத் தூறும் அறிவு\" — இக்குறளில் பயின்று வரும் அணி எது?","options":["உருவக அணி","வேற்றுமை அணி","எடுத்துக்காட்டு உவமையணி","பிறிது மொழிதல் அணி"],"correctAnswer":2,"explanation":"கல்வி அதிகாரத்தின் 396-ஆம் குறளில் மணற்கேணியைத் தோண்டத் தோண்ட நீர் ஊறுவது உவமையாகவும், மக்கள் கற்கக் கற்க அறிவு வளர்வது உவமேயமாகவும் வந்து, இடையில் 'போல' என்னும் உவம உருபு மறைந்து நிற்பதால் இது 'எடுத்துக்காட்டு உவமையணி' ஆகும்.","difficulty":"medium","topic":"பொருட்பால் – கல்வி"},{"id":458,"subject":"tamil","testNumber":5,"question":"\"கேடில் விழுச்செல்வம் கல்வி ஒருவற்கு / மாடல்ல மற்றை யவை\" — இக்குறளில் 'மாடு' என்னும் சொல் எதைக் குறிக்கிறது?","options":["விலங்கு","பக்கம்","அறிவு","செல்வம்"],"correctAnswer":3,"explanation":"கல்வி அதிகாரத்தின் 400-ஆம் குறளில் 'மாடு' என்பது 'செல்வம்' என்ற பழந் தமிழ் பொருளைத் தரும். அழிவில்லாத சிறந்த செல்வம் கல்வி மட்டுமே; கல்வியைத் தவிர மற்றப் பொன், பொருள் முதலியவை நிலையான செல்வங்கள் அல்ல என்பது இதன் பொருளாகும்.","difficulty":"easy","topic":"பொருட்பால் – கல்வி"},{"id":459,"subject":"tamil","testNumber":5,"question":"\"உளரென்னும் மாத்திரையர் அல்லால் பயவாக் / களரனையர் கல்லா தவர்\" — கல்லாதவரைத் திருவள்ளுவர் எதனோடு ஒப்பிடுகிறார்?","options":["பயிர் விளையாத களர்நிலம்","நீரற்ற கிணறு","கனியற்ற மரம்","சுவையற்ற உணவு"],"correctAnswer":0,"explanation":"கல்லாமை அதிகாரத்தின் 406-ஆம் குறளில், கல்வி கற்காதவர் உலகில் உயிரோடு இருக்கிறார் என்ற அளவில் மட்டுமே சொல்லப்படுவாரே தவிர, எந்தப் பயனும் விளையாத களர்நிலத்திற்கு (உவர் நிலத்திற்கு) ஒப்பானவர் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"medium","topic":"பொருட்பால் – கல்லாமை"},{"id":460,"subject":"tamil","testNumber":5,"question":"\"விலங்கொடு மக்கள் அனையர் இலங்குநூல் / கற்றாரோடு ஏனை யவர்\" — இக்குறளில் 'ஏனையவர்' யாரைக் குறிக்கிறது?","options":["செல்வந்தர்","வணிகர்","கல்லாதவர்","துறவியர்"],"correctAnswer":2,"explanation":"கல்லாமை அதிகாரத்தின் 410-ஆம் குறளில் 'ஏனையவர்' என்பது கல்வி கற்காதவரைக் குறிக்கும். அறம் முதலியவற்றை விளக்கும் சிறந்த நூல்களைக் கற்றவருக்கும் கல்லாதவருக்கும் உள்ள வேறுபாடு, மக்களுக்கும் விலங்குகளுக்கும் உள்ள வேறுபாட்டைப் போன்றது.","difficulty":"medium","topic":"பொருட்பால் – கல்லாமை"},{"id":461,"subject":"tamil","testNumber":5,"question":"\"செல்வத்துள் செல்வம் செவிச்செல்வம் அச்செல்வம் / _______\" — இக்குறளின் விடுபட்ட அடியைத் தேர்ந்தெடுக்கவும்.","options":["செல்வத்துள் எல்லாம் பெரிது","உலகத்துள் எல்லாம் தலை","கல்வியுள் எல்லாம் தலை","செல்வத்துள் எல்லாம் தலை"],"correctAnswer":3,"explanation":"கேள்வி அதிகாரத்தின் முதல் குறள் (குறள் 411): \"செல்வத்துள் செல்வம் செவிச்செல்வம் அச்செல்வம் / செல்வத்துள் எல்லாம் தலை\". எல்லாச் செல்வங்களிலும் சிறந்த செல்வம் செவியால் கேட்டறியும் கேள்விச் செல்வமே; அச்செல்வம் மற்ற எல்லாச் செல்வங்களுக்கும் தலையாயதாகும்.","difficulty":"easy","topic":"பொருட்பால் – கேள்வி"},{"id":462,"subject":"tamil","testNumber":5,"question":"\"எனைத்தானும் நல்லவை கேட்க அனைத்தானும் / ஆன்ற பெருமை தரும்\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["கேள்வி","கல்வி","அறிவுடைமை","பெரியாரைத் துணைக்கோடல்"],"correctAnswer":0,"explanation":"இக்குறள் பொருட்பாலின் 'கேள்வி' அதிகாரத்தில் (குறள் 416) இடம்பெற்றுள்ளது. எவ்வளவு சிறிய அளவிலாவது நல்ல கருத்துகளைச் செவியால் கேட்க வேண்டும்; அந்த அளவுக்கேனும் அது நிறைந்த பெருமையைத் தரும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – கேள்வி"},{"id":463,"subject":"tamil","testNumber":5,"question":"\"அறிவற்றம் காக்கும் கருவி செறுவார்க்கும் / உள்ளழிக்கல் ஆகா அரண்\" — இக்குறளில் 'அற்றம்' என்பதன் பொருள் யாது?","options":["செல்வம்","வீரம்","அழிவு","புகழ்"],"correctAnswer":2,"explanation":"அறிவுடைமை அதிகாரத்தின் முதல் குறளில் (குறள் 421) 'அற்றம்' என்றால் 'அழிவு' எனப் பொருள். அறிவு என்பது அழிவு வராமல் காக்கும் கருவியாகும்; மேலும் பகைவர்களால் உள்ளே புகுந்து அழிக்க முடியாத பாதுகாப்பு அரணும் ஆகும்.","difficulty":"medium","topic":"பொருட்பால் – அறிவுடைமை"},{"id":464,"subject":"tamil","testNumber":5,"question":"\"எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள் / மெய்ப்பொருள் காண்ப தறிவு\" — இக்குறள் உணர்த்தும் 'அறிவு' எது?","options":["பிறர் கூறுவதை அப்படியே நம்புதல்","பழைய நூல்களை மட்டும் படித்தறிதல்","அதிகாரத்தில் உள்ளோர் சொல்வதை ஏற்றல்","யார் எதைச் சொன்னாலும் அதன் உண்மைப் பொருளை ஆராய்ந்து அறிதல்"],"correctAnswer":3,"explanation":"அறிவுடைமை அதிகாரத்தின் 423-ஆம் குறளில், எந்தப் பொருளை யார் யார் வாயிலாகக் கேட்டாலும், சொல்பவரை நோக்காமல் அக்கருத்தின் உண்மைப் பொருளை (மெய்ப்பொருளை) ஆராய்ந்து தெளிவதே பகுத்தறிவு எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"easy","topic":"பொருட்பால் – அறிவுடைமை"},{"id":465,"subject":"tamil","testNumber":5,"question":"\"அரியவற்றுள் எல்லாம் அரிதே பெரியாரைப் / பேணித் தமராக் கொளல்\" — இக்குறளில் 'தமர்' என்பதன் பொருள் என்ன?","options":["சுற்றத்தார் (தம்மவர்)","பகைவர்","அமைச்சர்","பணியாளர்"],"correctAnswer":0,"explanation":"பெரியாரைத் துணைக்கோடல் அதிகாரத்தின் 443-ஆம் குறளில் 'தமர்' என்பது தம்மவர் அல்லது சுற்றத்தார் எனப் பொருள்படும். பெறற்கரிய பேறுகள் எல்லாவற்றிலும் மிக அரியது அறிவுடைய பெரியாரைப் போற்றித் தமக்குரிய துணையாகக் கொள்வதாகும்.","difficulty":"hard","topic":"பொருட்பால் – பெரியாரைத் துணைக்கோடல்"},{"id":466,"subject":"tamil","testNumber":5,"question":"\"இடிப்பாரை இல்லாத ஏமரா மன்னன் / கெடுப்பார் இலானும் கெடும்\" — இக்குறளில் 'இடிப்பாரை' என்பது யாரைக் குறிக்கிறது?","options":["பகைவர்களைத் தாக்கும் வீரர்கள்","வரி வசூலிக்கும் அலுவலர்கள்","குற்றம் கண்டபோது கடிந்து அறிவுரை கூறும் பெரியோர்","கோட்டை மதில்களைக் காக்கும் காவலர்கள்"],"correctAnswer":2,"explanation":"பெரியாரைத் துணைக்கோடல் அதிகாரத்தின் 448-ஆம் குறளில் 'இடிப்பார்' என்பது அரசன் தவறு செய்யும்போது அஞ்சாமல் கடிந்து நல்வழிப்படுத்தும் அறிவுடைய பெரியோரைக் குறிக்கும். அத்தகையோர் துணை இல்லாத பாதுகாப்பற்ற அரசன், தன்னைக் கெடுக்கும் பகைவர் எவரும் இல்லாவிட்டாலும் தானாகவே அழிந்துவிடுவான்.","difficulty":"medium","topic":"பொருட்பால் – பெரியாரைத் துணைக்கோடல்"},{"id":467,"subject":"tamil","testNumber":5,"question":"\"ஈன்றாள் பசிகாண்பான் ஆயினும் செய்யற்க / சான்றோர் பழிக்கும் வினை\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["வினைத்திட்பம்","வினைசெயல்வகை","வினைத்தூய்மை","தெரிந்து வினையாடல்"],"correctAnswer":2,"explanation":"இக்குறள் பொருட்பால் அமைச்சியலில் உள்ள 'வினைத்தூய்மை' அதிகாரத்தில் (குறள் 656) இடம்பெற்றுள்ளது. தன்னைப் பெற்ற தாயின் பசியைப் போக்குவதற்காக என்றாலும், சான்றோர் பழிக்கும் தீய செயலை ஒருபோதும் செய்யக் கூடாது என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – வினைத்தூய்மை"},{"id":468,"subject":"tamil","testNumber":5,"question":"\"சலத்தால் பொருள்செய்தே மார்த்தல் பசுமண் / கலத்துநீர் பெய்திரீஇ யற்று\" — தீய வழியில் பொருள் சேர்த்துக் காப்பதை வள்ளுவர் எதனோடு ஒப்பிடுகிறார்?","options":["சுடாத பச்சை மண் பாண்டத்தில் நீரை ஊற்றி வைத்தல்","உடைந்த ஓடத்தில் கடலைக் கடத்தல்","கனியிருக்கும்போது காயைப் பறித்தல்","மணலில் அணை கட்டுதல்"],"correctAnswer":0,"explanation":"வினைத்தூய்மை அதிகாரத்தின் 660-ஆம் குறளில் 'சலம்' என்பது வஞ்சனை அல்லது தீய வழி. தீய வழியில் பொருள் ஈட்டி அதனைப் பாதுகாத்தல், சுடப்படாத பச்சை மண் கலத்தில் நீரை ஊற்றி வைத்துக் காப்பது போல் பொருளும் பாத்திரமும் சேர்ந்து அழிந்துவிடும் என்பது இதன் கருத்தாகும்.","difficulty":"hard","topic":"பொருட்பால் – வினைத்தூய்மை"},{"id":469,"subject":"tamil","testNumber":5,"question":"\"வினைத்திட்பம் என்பது ஒருவன் _______ / மற்றைய எல்லாம் பிற\" — விடுபட்ட சீரைத் தேர்ந்தெடுக்கவும்.","options":["படைத்திட்பம்","உடல்திட்பம்","சொல்திட்பம்","மனத்திட்பம்"],"correctAnswer":3,"explanation":"வினைத்திட்பம் அதிகாரத்தின் முதல் குறள் (குறள் 661): \"வினைத்திட்பம் என்பது ஒருவன் மனத்திட்பம் / மற்றைய எல்லாம் பிற\". ஒரு செயலைச் செய்து முடிக்கும் வலிமை என்பது ஒருவனுடைய மனத்தின் உறுதிப்பாடே ஆகும்; மற்றப் படை, பொருள் முதலியன பிற துணைக்கருவிகள் மட்டுமே.","difficulty":"easy","topic":"பொருட்பால் – வினைத்திட்பம்"},{"id":470,"subject":"tamil","testNumber":5,"question":"\"சொல்லுதல் யார்க்கும் எளிய அரியவாம் / சொல்லிய வண்ணம் செயல்\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["சொல்வன்மை","வாய்மை","வினைத்திட்பம்","ஊக்கமுடைமை"],"correctAnswer":2,"explanation":"இக்குறள் பொருட்பாலில் உள்ள 'வினைத்திட்பம்' அதிகாரத்தின் 664-ஆம் குறளாகும். ஒரு செயலை இவ்வாறு செய்து முடிப்பேன் என்று வாயால் சொல்வது அனைவருக்கும் எளிதானது; ஆனால் சொன்னபடியே அச்செயலைச் செய்து முடிப்பது மிகவும் அரிதானதாகும்.","difficulty":"medium","topic":"பொருட்பால் – வினைத்திட்பம்"},{"id":471,"subject":"tamil","testNumber":5,"question":"\"பகல்வெல்லும் கூகையைக் காக்கை இகல்வெல்லும் / வேந்தர்க்கு வேண்டும் பொழுது\" — இக்குறளில் 'கூகை' என்பதன் பொருள் யாது?","options":["கோட்டான் (ஆந்தை)","கழுகு","வல்லூறு","மயில்"],"correctAnswer":0,"explanation":"காலமறிதல் அதிகாரத்தின் முதல் குறளில் (குறள் 481) 'கூகை' என்பது கோட்டானை (ஆந்தையை) குறிக்கும். தன்னைவிட வலிமை மிக்க கோட்டானைக் காக்கை பகல் நேரத்தில் வென்றுவிடும்; அதுபோலப் பகையை வெல்ல விரும்பும் அரசனுக்குத் தக்க காலத்தை அறிதல் மிகவும் இன்றியமையாதது.","difficulty":"medium","topic":"பொருட்பால் – காலமறிதல்"},{"id":472,"subject":"tamil","testNumber":5,"question":"\"கொக்கொக்க கூம்பும் பருவத்து மற்றதன் / குத்தொக்க சீர்த்த இடத்து\" — இக்குறளில் பயின்று வரும் அணி எது?","options":["பிறிது மொழிதல் அணி","உருவக அணி","வேற்றுமை அணி","உவமையணி"],"correctAnswer":3,"explanation":"காலமறிதல் அதிகாரத்தின் 490-ஆம் குறளில் 'ஒக்க' (போல) என்னும் உவம உருபு வெளிப்படையாக வந்துள்ளதால் இது 'உவமையணி' ஆகும். வாய்ப்பில்லாத காலத்தில் கொக்குபோல் அமைதியாகக் காத்திருக்க வேண்டும்; தக்க வாய்ப்பு வந்ததும் கொக்கு மீனைக் கொத்துவது போல் விரைந்து செயலை முடிக்க வேண்டும்.","difficulty":"medium","topic":"பொருட்பால் – காலமறிதல்"},{"id":473,"subject":"tamil","testNumber":5,"question":"\"கடலோடா கால்வல் நெடுந்தேர் கடலோடும் / நாவாயும் ஓடா நிலத்து\" — இக்குறளில் பயின்று வரும் அணி எது?","options":["பிறிது மொழிதல் அணி","எடுத்துக்காட்டு உவமையணி","சொற்பொருள் பின்வருநிலையணி","தற்குறிப்பேற்ற அணி"],"correctAnswer":0,"explanation":"இடனறிதல் அதிகாரத்தின் 496-ஆம் குறளில், வலிமையான சக்கரங்களையுடைய பெரிய தேர் கடலில் ஓடாது; கடலில் ஓடும் கப்பலும் நிலத்தில் ஓடாது என்ற உவமையை மட்டும் கூறி, அதன் மூலம் அவரவர் தமக்குரிய இடத்தில் இருந்தாலே சிறப்பாகச் செயல்பட முடியும் என்ற பொருளைப் பெற வைப்பதால் இது 'பிறிது மொழிதல் அணி' ஆகும்.","difficulty":"hard","topic":"பொருட்பால் – இடனறிதல்"},{"id":474,"subject":"tamil","testNumber":5,"question":"\"தொடங்கற்க எவ்வினையும் எள்ளற்க முற்றும் / இடங்கண்ட பின்னல் லது\" — இக்குறளின்படி எதை முழுமையாக ஆராய்ந்த பிறகே ஒரு செயலைத் தொடங்க வேண்டும்?","options":["பொருள் வளம்","தகுந்த இடம்","படை வலிமை","பகைவரின் வயது"],"correctAnswer":1,"explanation":"இடனறிதல் அதிகாரத்தின் முதல் குறள் (குறள் 491) இது. தக்க இடத்தை முழுமையாக ஆராய்ந்து கண்டறியாமல் எந்த ஒரு செயலையும் தொடங்கக் கூடாது; பகைவரை இகழ்ந்து எளிதாக எடைபோடவும் கூடாது என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – இடனறிதல்"},{"id":475,"subject":"tamil","testNumber":5,"question":"\"ஓர்ந்துகண் ணோடாது இறைபுரிந்து யார்மாட்டும் / தேர்ந்துசெய் வஃதே முறை\" — இக்குறள் எந்த அதிகாரத்தில் இடம்பெற்றுள்ளது?","options":["இறைமாட்சி","குடியோம்பல்","செங்கோன்மை","வெருவந்த செய்யாமை"],"correctAnswer":2,"explanation":"இக்குறள் பொருட்பாலின் 'செங்கோன்மை' அதிகாரத்தின் முதல் குறளாகும் (குறள் 541). குற்றத்தை நன்கு ஆராய்ந்து, யாரிடமும் விருப்பு வெறுப்பின்றி நடுவுநிலைமையோடு நடந்து, நூலோருடன் கலந்தாலோசித்துத் தக்க தண்டனை வழங்குவதே சிறந்த ஆட்சி முறையாகும்.","difficulty":"hard","topic":"பொருட்பால் – செங்கோன்மை"},{"id":476,"subject":"tamil","testNumber":5,"question":"\"வானோக்கி வாழும் உலகெல்லாம் மன்னவன் / கோல்நோக்கி வாழும் குடி\" — இக்குறளில் 'கோல்' என்பது எதைக் குறிக்கிறது?","options":["அரசனின் செங்கோல் (நீதியான ஆட்சி)","போர்க் கருவி","அளவைக் கோல்","பயிர் வளர்ச்சி"],"correctAnswer":0,"explanation":"செங்கோன்மை அதிகாரத்தின் 542-ஆம் குறளில் 'கோல்' என்பது அரசனின் நீதியான செங்கோல் ஆட்சியைக் குறிக்கும். உலகத்து உயிர்கள் எல்லாம் மழையை எதிர்நோக்கி வாழ்வதுபோல, நாட்டின் குடிமக்கள் அனைவரும் அரசனின் செங்கோலாட்சியை நம்பியே வாழ்கின்றனர்.","difficulty":"easy","topic":"பொருட்பால் – செங்கோன்மை"},{"id":477,"subject":"tamil","testNumber":5,"question":"\"கருவியும் காலமும் செய்கையும் செய்யும் / அருவினையும் மாண்ட தமைச்சு\" — இக்குறளின்படி சிறந்த அமைச்சருக்கு உரிய நான்கு கூறுகளுள் இடம்பெறாதது எது?","options":["கருவி (துணைக்கருவிகள்)","காலம் (தக்க காலம்)","செய்கை (செய்யும் முறை)","படைத்தலைமை"],"correctAnswer":3,"explanation":"அமைச்சு அதிகாரத்தின் முதல் குறளில் (குறள் 631) ஒரு செயலுக்கு வேண்டிய கருவி, ஏற்ற காலம், செய்யும் முறை, செய்யப்படும் அரிய செயல் ஆகிய நான்கையும் திறம்பட ஆராய்ந்து முடிப்பவரே சிறந்த அமைச்சர் எனத் திருவள்ளுவர் வரையறுக்கிறார்; படைத்தலைமை இதில் குறிப்பிடப்படவில்லை.","difficulty":"hard","topic":"பொருட்பால் – அமைச்சு"},{"id":478,"subject":"tamil","testNumber":5,"question":"\"விரைந்து தொழில்கேட்கும் ஞாலம் நிரந்தினிது / சொல்லுதல் வல்லார்ப் பெறின்\" — இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["சொல்வன்மை","அவை அறிதல்","அவை அஞ்சாமை","தூது"],"correctAnswer":0,"explanation":"இக்குறள் பொருட்பாலின் 'சொல்வன்மை' அதிகாரத்தில் (குறள் 648) அமைந்துள்ளது. கருத்துகளை முறைப்படுத்தி (நிரந்து) கேட்போர் மனம் மகிழும்படி இனிமையாகச் சொல்ல வல்லவரைப் பெற்றால், அவருடைய ஏவலை இவ்வுலகம் விரைந்து கேட்டு நடக்கும் என்பது இதன் பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – சொல்வன்மை"},{"id":479,"subject":"tamil","testNumber":5,"question":"\"உறுபசியும் ஓவாப் பிணியும் செறுபகையும் / சேரா தியல்வது நாடு\" — இக்குறளில் 'ஓவாப் பிணி' என்பதன் பொருள் யாது?","options":["நீங்காத நோய்","தொற்று நோய்","உடனடி நோய்","மன நோய்"],"correctAnswer":0,"explanation":"நாடு அதிகாரத்தின் 734-ஆம் குறளில் 'ஓவாப் பிணி' என்பது நீங்காத (இடைவிடாத) நோயைக் குறிக்கும். மிகுந்த பசியும், நீங்காத நோயும், அழிவு செய்யும் பகையும் சேராமல் இயங்குவதே சிறந்த நாடாகும் என்பது இக்குறளின் பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – நாடு"},{"id":480,"subject":"tamil","testNumber":5,"question":"\"மணிநீரும் மண்ணும் மலையும் அணிநிழற் / காடும் உடைய தரண்\" — இக்குறளின்படி சிறந்த அரணுக்கு (கோட்டைக்கு) உரிய நான்கு இயற்கை உறுப்புகள் எவை?","options":["தெளிந்த நீர், வெட்டவெளி நிலம், மலை, குளிர்ந்த காடு","கடல், ஆறு, வயல், மலை","அகழி, மதில், கோபுரம், யானைப்படை","வயல், பாலைவனம், மலை, கடல்"],"correctAnswer":0,"explanation":"அரண் அதிகாரத்தின் 742-ஆம் குறளில், மணிபோல் தெளிந்த நீரும் (மணிநீர்), அகன்ற வெட்டவெளி நிலமும் (மண்), உயர்ந்த மலையும், அழகிய குளிர்ந்த நிழலையுடைய காடும் ஆகிய நான்கு இயற்கைப் பாதுகாப்புகளையும் கொண்டதே சிறந்த அரண் எனத் திருவள்ளுவர் குறிப்பிடுகிறார்.","difficulty":"easy","topic":"பொருட்பால் – அரண்"},{"id":481,"subject":"tamil","testNumber":5,"question":"\"நவில்தொறும் நூல்நயம் போலும் பயில்தொறும் / பண்புடை யாளர் தொடர்பு\" — பண்புடையாளரின் நட்பை வள்ளுவர் எதனோடு ஒப்பிடுகிறார்?","options":["கடலின் ஆழத்தோடு","மலரின் நறுமணத்தோடு","நல்ல நூலைக் கற்கக் கற்க இன்பம் தருவதோடு","நிலவின் குளிர்ச்சியோடு"],"correctAnswer":2,"explanation":"நட்பு அதிகாரத்தின் 783-ஆம் குறளில், சிறந்த நூலைப் படிக்கப் படிக்க அதன் சுவையும் பொருள் நயமும் மேலும் மேலும் இன்பம் தருவது போல, நற்பண்பு உடையவரோடு பழகப் பழக அவருடைய நட்பு மேலும் இன்பம் தரும் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"easy","topic":"பொருட்பால் – நட்பு"},{"id":482,"subject":"tamil","testNumber":5,"question":"\"உடுக்கை இழந்தவன் கைபோல ஆங்கே / இடுக்கண் களைவதாம் நட்பு\" — இக்குறளில் 'இடுக்கண்' என்பதன் பொருள் என்ன?","options":["வறுமை","குற்றம்","துன்பம்","அச்சம்"],"correctAnswer":2,"explanation":"நட்பு அதிகாரத்தின் 788-ஆம் குறளில் 'இடுக்கண்' என்பது துன்பத்தைக் குறிக்கும். உடுத்திய ஆடை நெகிழ்ந்தபோது ஒருவனின் கை உடனே விரைந்து சென்று அதனைச் சரிசெய்து மானம் காப்பது போல, நண்பனுக்குத் துன்பம் வந்த உடனே அதனைப் போக்குவதே உண்மையான நட்பாகும்.","difficulty":"easy","topic":"பொருட்பால் – நட்பு"},{"id":483,"subject":"tamil","testNumber":5,"question":"\"தொழுதகை யுள்ளும் படையொடுங்கும் ஒன்னார் / அழுதகண் ணீரும் அனைத்து\" — இக்குறளில் 'ஒன்னார்' என்பதன் பொருள் யாது?","options":["நண்பர்கள்","உறவினர்கள்","அமைச்சர்கள்","பகைவர்கள்"],"correctAnswer":3,"explanation":"கூடாநட்பு அதிகாரத்தின் 828-ஆம் குறளில் 'ஒன்னார்' என்பது பகைவரைக் குறிக்கும். பகைவர் வணங்கிக் குவித்த கைகளுக்குள்ளும் கொலைக்கருவி மறைந்திருக்கக் கூடும்; அதுபோல அவர்கள் அழுது வடிக்கும் கண்ணீரும் வஞ்சனை நிறைந்ததே ஆகும்.","difficulty":"hard","topic":"பொருட்பால் – கூடாநட்பு"},{"id":484,"subject":"tamil","testNumber":5,"question":"\"சுழன்றும்ஏர்ப் பின்னது உலகம் அதனால் / உழந்தும் உழவே தலை\" — இக்குறளில் 'உழந்தும்' என்பதன் பொருள் என்ன?","options":["மகிழ்ந்தும்","விரைந்தும்","வருந்தியும்","சிந்தித்தும்"],"correctAnswer":2,"explanation":"உழவு அதிகாரத்தின் முதல் குறளில் (குறள் 1031) 'உழந்தும்' என்றால் 'வருந்தியும்' என்று பொருள். உலகம் எத்தனை தொழில்களைச் செய்து சுழன்றாலும் இறுதியில் ஏர் (உழவு) தொழிலுக்குப் பின்னாலேயே நிற்க வேண்டியுள்ளது; ஆதலால் எவ்வளவு வருந்தினாலும் உழவுத் தொழிலே தலைசிறந்ததாகும்.","difficulty":"medium","topic":"பொருட்பால் – உழவு"},{"id":485,"subject":"tamil","testNumber":5,"question":"\"உழுதுண்டு வாழ்வாரே வாழ்வார்மற் றெல்லாம் / தொழுதுண்டு பின்செல் பவர்\" — இக்குறள் இடம்பெறும் பால் மற்றும் இயல் எவை?","options":["அறத்துப்பால் – இல்லறவியல்","பொருட்பால் – அரசியல்","பொருட்பால் – அமைச்சியல்","பொருட்பால் – ஒழிபியல்"],"correctAnswer":3,"explanation":"உழவு அதிகாரம் (அதிகாரம் 104, குறள் 1033) பொருட்பாலின் மூன்றாவது இயலான 'ஒழிபியல்' பகுதியில் இடம்பெற்றுள்ளது. உழவுத் தொழில் செய்து உணவு உண்டு வாழ்பவரே உரிமையோடு வாழ்பவர்; மற்றவர்கள் அனைவரும் பிறரைத் தொழுது உண்டு பின்செல்பவர்களே ஆவர்.","difficulty":"hard","topic":"பொருட்பால் – உழவு"},{"id":486,"subject":"tamil","testNumber":5,"question":"\"இன்மையின் இன்னாதது யாதெனின் இன்மையின் / இன்மையே இன்னா தது\" — இக்குறள் இடம்பெறும் 'நல்குரவு' என்ற அதிகாரப் பெயரின் பொருள் யாது?","options":["நல்லுறவு","நல்லறிவு","வறுமை","செல்வம்"],"correctAnswer":2,"explanation":"பொருட்பாலின் ஒழிபியலில் உள்ள 'நல்குரவு' (அதிகாரம் 105) என்பதன் பொருள் 'வறுமை' ஆகும். வறுமையை விடத் துன்பம் தருவது வேறு எது என்று கேட்டால், வறுமையைப் போலத் துன்பம் தருவது அந்த வறுமையே அன்றி வேறில்லை என்பது இக்குறளின் (1041) பொருளாகும்.","difficulty":"medium","topic":"பொருட்பால் – நல்குரவு"},{"id":487,"subject":"tamil","testNumber":5,"question":"\"அன்புநாண் ஒப்புரவு கண்ணோட்டம் வாய்மையொடு / ஐந்துசால்பு ஊன்றிய தூண்\" — இக்குறளில் சான்றாண்மையைத் தாங்கும் ஐந்து தூண்களுள் இடம்பெறாத பண்பு எது?","options":["அன்பு","நாணம்","கண்ணோட்டம்","செல்வம்"],"correctAnswer":3,"explanation":"சான்றாண்மை அதிகாரத்தின் 983-ஆம் குறளில் அன்பு, நாணம் (பழிக்கு அஞ்சுதல்), ஒப்புரவு (உலக நடைக்கு ஏற்ப உதவுதல்), கண்ணோட்டம் (இரக்கம்), வாய்மை ஆகிய ஐந்து நற்பண்புகளே சான்றாண்மை என்னும் மாளிகையைத் தாங்கி நிற்கும் தூண்கள் எனக் கூறப்பட்டுள்ளது.","difficulty":"medium","topic":"பொருட்பால் – சான்றாண்மை"},{"id":488,"subject":"tamil","testNumber":5,"question":"\"ஊழி பெயரினும் தாம் பெயரார் சான்றாண்மைக்கு / ஆழி எனப்படு வார்\" — இக்குறள் உணர்த்தும் கருத்து எது?","options":["கடலைக் கடப்பவரே சான்றோர்","ஊழிக்காலமே மாறி உலகம் அழிந்தாலும் சான்றோர் தம் நற்பண்பிலிருந்து மாற மாட்டார்","காலத்திற்கு ஏற்ப சான்றோர் தம் கொள்கையை மாற்றிக் கொள்வர்","ஊழ்வினையை வெல்ல யாராலும் இயலாது"],"correctAnswer":1,"explanation":"சான்றாண்மை அதிகாரத்தின் 989-ஆம் குறளில், சான்றாண்மை என்னும் கடலுக்குக் கரை போன்றவராகப் போற்றப்படும் சான்றோர், ஊழிக்காலமே மாறி உலகம் நிலைகுலைந்தாலும் தமது நற்பண்புகளிலிருந்து ஒருபோதும் நிலைமாற மாட்டார்கள் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"hard","topic":"பொருட்பால் – சான்றாண்மை"},{"id":489,"subject":"tamil","testNumber":5,"question":"\"அரம்போலும் கூர்மைய ரேனும் மரம்போல்வர் / மக்கட்பண் பில்லா தவர்\" — மக்கள் பண்பு இல்லாதவர்களைத் திருவள்ளுவர் எதனோடு ஒப்பிடுகிறார்?","options":["கல்","விலங்கு","மரம்","கூர்மையான அரம்"],"correctAnswer":2,"explanation":"பண்புடைமை அதிகாரத்தின் 997-ஆம் குறளில், அரத்தைப் போன்ற மிகக் கூர்மையான அறிவு உடையவர்களாக இருந்தாலும், மக்களுக்குரிய நற்பண்பு இல்லாதவர்கள் ஓரறிவுடைய மரத்தைப் போன்றவர்களே ஆவர் எனத் திருவள்ளுவர் கூறுகிறார்.","difficulty":"easy","topic":"பொருட்பால் – பண்புடைமை"},{"id":490,"subject":"tamil","testNumber":5,"question":"\"மருந்தென வேண்டாவாம் யாக்கைக்கு அருந்தியது / அற்றது போற்றி உணின்\" — இக்குறளின்படி உடலுக்கு மருந்து எப்போது தேவைப்படாது?","options":["தினமும் இரண்டு வேளை மட்டுமே உண்டால்","முன் உண்ட உணவு செரித்ததை அறிந்து அடுத்த உணவை உண்டால்","காய்கறிகளை மட்டுமே உண்டு வாழ்ந்தால்","நீர் அதிகமாக அருந்தி வந்தால்"],"correctAnswer":1,"explanation":"மருந்து அதிகாரத்தின் 942-ஆம் குறளில், முன் உண்ட உணவு நன்கு செரித்ததை அறிந்து ('அற்றது போற்றி') அதன் பிறகு அளவோடு உண்டால், ஒருவருடைய உடலுக்கு (யாக்கைக்கு) மருந்து என ஒன்று தேவைப்படவே படாது எனத் திருவள்ளுவர் மருத்துவ உண்மையைக் கூறுகிறார்.","difficulty":"easy","topic":"பொருட்பால் – மருந்து"},{"id":491,"subject":"tamil","testNumber":5,"question":"திருக்குறளின் காமத்துப்பாலில் உள்ள இரண்டு இயல்கள் மற்றும் அவற்றின் அதிகார எண்ணிக்கை முறையே எவை?","options":["களவியல் – 7 அதிகாரங்கள், கற்பியல் – 18 அதிகாரங்கள்","களவியல் – 10 அதிகாரங்கள், கற்பியல் – 15 அதிகாரங்கள்","களவியல் – 8 அதிகாரங்கள், கற்பியல் – 17 அதிகாரங்கள்","களவியல் – 12 அதிகாரங்கள், கற்பியல் – 13 அதிகாரங்கள்"],"correctAnswer":0,"explanation":"திருக்குறளின் மூன்றாம் பாலான காமத்துப்பால் (இன்பத்துப்பால்) மொத்தம் 25 அதிகாரங்களைக் கொண்டுள்ளது. இது களவியல் (7 அதிகாரங்கள்: 109–115) மற்றும் கற்பியல் (18 அதிகாரங்கள்: 116–133) என இரு இயல்களாகப் பகுக்கப்பட்டுள்ளது.","difficulty":"medium","topic":"காமத்துப்பால் – அமைப்பு"},{"id":492,"subject":"tamil","testNumber":5,"question":"\"கண்ணொடு கண்ணிணை நோக்கொக்கின் வாய்ச்சொற்கள் / என்ன பயனும் இல\" — இக்குறள் இடம்பெறும் பால் மற்றும் அதிகாரம் எவை?","options":["அறத்துப்பால் – அன்புடைமை","பொருட்பால் – நட்பு","காமத்துப்பால் – குறிப்பறிதல்","பொருட்பால் – குறிப்பறிதல்"],"correctAnswer":2,"explanation":"இக்குறள் காமத்துப்பாலின் களவியலில் உள்ள 'குறிப்பறிதல்' அதிகாரத்தின் (அதிகாரம் 110, குறள் 1100) இறுதிக் குறளாகும். காதலர் இருவரின் கண்களும் ஒன்றையொன்று அன்போடு நோக்கி ஒத்திருந்தால், வாயால் பேசும் சொற்களால் ஒரு பயனும் இல்லை என்பது இதன் பொருளாகும்.","difficulty":"hard","topic":"காமத்துப்பால் – களவியல்"},{"id":493,"subject":"tamil","testNumber":5,"question":"\"அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை / மாதர்கொல் மாலும்என் நெஞ்சு\" — காமத்துப்பாலின் முதல் குறளான (1081) இது எந்த இயலில் இடம்பெற்றுள்ளது?","options":["கற்பியல்","களவியல்","ஒழிபியல்","இல்லறவியல்"],"correctAnswer":1,"explanation":"காமத்துப்பாலின் முதல் அதிகாரமான 'தகையணங்குறுத்தல்' (அதிகாரம் 109) களவியலில் அமைந்துள்ளது. தலைவியைக் கண்ட தலைவன் இவள் தெய்வப்பெண்ணோ, அழகிய மயிலோ, கனமான காதணி அணிந்த மனிதப் பெண்ணோ என என் நெஞ்சம் மயங்குகிறதே என வியக்கும் காட்சியை இக்குறள் சித்தரிக்கிறது.","difficulty":"hard","topic":"காமத்துப்பால் – களவியல்"},{"id":494,"subject":"tamil","testNumber":5,"question":"\"ஊடுதல் காமத்திற்கு இன்பம் அதற்கின்பம் / கூடி முயங்கப் பெறின்\" — திருக்குறளின் 1,330-ஆவது (இறுதி) குறள் இடம்பெறும் அதிகாரம் எது?","options":["புலவி","புலவி நுணுக்கம்","ஊடலுவகை","நலம்புனைந்துரைத்தல்"],"correctAnswer":2,"explanation":"திருக்குறளின் 133-ஆவது மற்றும் இறுதி அதிகாரம் கற்பியலில் உள்ள 'ஊடலுவகை' ஆகும். இதன் இறுதிக் குறளான 1,330-ஆவது குறள் காதலர் இடையே ஏற்படும் சிறு ஊடலும், அதன் பின் கூடித் தழுவுதலும் காதலுக்குப் பேரின்பம் தரும் என்பதை உணர்த்துகிறது.","difficulty":"medium","topic":"காமத்துப்பால் – கற்பியல்"},{"id":495,"subject":"tamil","testNumber":5,"question":"\"உப்பமைந் தற்றால் புலவி அதுசிறிது / மிக்கற்றால் நீள விடல்\" — இக்குறளில் ஊடலை (புலவியை) திருவள்ளுவர் எதனோடு ஒப்பிடுகிறார்?","options":["அனிச்ச மலர்","தேன்","உணவில் அளவோடு இடும் உப்பு","மழைத்துளி"],"correctAnswer":2,"explanation":"காமத்துப்பால் கற்பியலில் உள்ள 'புலவி' அதிகாரத்தில் (குறள் 1302) உணவில் அளவோடு சேர்க்கப்படும் உப்பு சுவை தருவதுபோலக் காதலில் அளவான ஊடல் இன்பம் தரும்; ஆனால் உப்பு சிறிது மிகுந்தால் உணவு கெடுவதுபோல ஊடலை நீள விட்டால் இன்பம் கெடும் என வள்ளுவர் உவமிக்கிறார்.","difficulty":"medium","topic":"காமத்துப்பால் – கற்பியல்"},{"id":496,"subject":"tamil","testNumber":5,"question":"\"பிறப்பொக்கும் எல்லா உயிர்க்கும் சிறப்பொவ்வா / செய்தொழில் வேற்றுமை யான்\" — உலகப் புகழ்பெற்ற இக்குறள் இடம்பெறும் அதிகாரம் எது?","options":["ஒழுக்கமுடைமை","சான்றாண்மை","பண்புடைமை","பெருமை"],"correctAnswer":3,"explanation":"இக்குறள் பொருட்பாலின் ஒழிபியலில் உள்ள 'பெருமை' அதிகாரத்தில் (அதிகாரம் 98, குறள் 972) இடம்பெற்றுள்ளது. பிறப்பால் எல்லா உயிர்களும் சமமே; ஆனால் அவை செய்கின்ற தொழில்களின் ஏற்றத்தாழ்வு காரணமாகவே சிறப்புகளில் வேறுபாடு ஏற்படுகிறது என்ற சமத்துவக் கருத்தை இக்குறள் முழங்குகிறது.","difficulty":"medium","topic":"திருக்குறள் பொன்மொழிகள்"},{"id":497,"subject":"tamil","testNumber":5,"question":"\"யாதானும் நாடாமால் ஊராமால் என்னொருவன் / சாந்துணையும் கல்லாத வாறு\" — இக்குறளில் 'சாந்துணையும்' என்பதன் பொருள் யாது?","options":["இளமை வரையிலும்","முதுமை தொடங்கும் வரையிலும்","பொருள் சேர்க்கும் வரையிலும்","சாகும் வரையிலும்"],"correctAnswer":3,"explanation":"கல்வி அதிகாரத்தின் 397-ஆம் குறளில் 'சாந்துணையும்' என்றால் 'சாகும் வரையிலும்' என்று பொருள். கற்றவனுக்கு எந்த நாடும் தன் நாடாகும், எந்த ஊரும் தன் ஊராகும்; அவ்வாறிருக்க ஒருவன் சாகும் வரையிலும் கல்வி கற்காமல் இருப்பது ஏனோ என வள்ளுவர் வினவுகிறார்.","difficulty":"medium","topic":"திருக்குறள் பொன்மொழிகள்"},{"id":498,"subject":"tamil","testNumber":5,"question":"பொருத்துக (பொருட்பால் மற்றும் இன்பத்துப்பால் இயல்கள் – அதிகார எண்ணிக்கை):\nஅ) அரசியல் — 1) 18 அதிகாரங்கள்\nஆ) அமைச்சியல் — 2) 7 அதிகாரங்கள்\nஇ) களவியல் — 3) 25 அதிகாரங்கள்\nஈ) கற்பியல் — 4) 32 அதிகாரங்கள்","options":["அ-3, ஆ-4, இ-2, ஈ-1","அ-4, ஆ-3, இ-2, ஈ-1","அ-3, ஆ-2, இ-4, ஈ-1","அ-1, ஆ-4, இ-2, ஈ-3"],"correctAnswer":0,"explanation":"திருக்குறள் இயல்களின் அதிகார எண்ணிக்கை: பொருட்பாலில் அரசியல் – 25 அதிகாரங்கள், அமைச்சியல் – 32 அதிகாரங்கள் (மற்றும் ஒழிபியல் – 13 அதிகாரங்கள்); காமத்துப்பாலில் களவியல் – 7 அதிகாரங்கள், கற்பியல் – 18 அதிகாரங்கள். எனவே சரியான பொருத்தம் அ-3, ஆ-4, இ-2, ஈ-1 ஆகும்.","difficulty":"hard","topic":"திருக்குறள் – பொருத்துக"},{"id":499,"subject":"tamil","testNumber":5,"question":"பொருத்துக (அதிகாரம் – புகழ்பெற்ற குறள் தொடர்):\nஅ) ஊக்கமுடைமை — 1) ஊருணி நீர்நிறைந் தற்றே\nஆ) ஆள்வினையுடைமை — 2) இடும்பைக்கு இடும்பை படுப்பர்\nஇ) இடுக்கண் அழியாமை — 3) அருமை உடைத்தென்று அசாவாமை வேண்டும்\nஈ) ஒப்புரவறிதல் — 4) வெள்ளத் தனைய மலர்நீட்டம்","options":["அ-4, ஆ-3, இ-2, ஈ-1","அ-3, ஆ-4, இ-1, ஈ-2","அ-4, ஆ-2, இ-3, ஈ-1","அ-1, ஆ-3, இ-2, ஈ-4"],"correctAnswer":0,"explanation":"வெள்ளத் தனைய மலர்நீட்டம் (குறள் 595) – ஊக்கமுடைமை; அருமை உடைத்தென்று அசாவாமை வேண்டும் (குறள் 611) – ஆள்வினையுடைமை; இடும்பைக்கு இடும்பை படுப்பர் (குறள் 623) – இடுக்கண் அழியாமை; ஊருணி நீர்நிறைந் தற்றே (குறள் 215) – ஒப்புரவறிதல். எனவே சரியான பொருத்தம் அ-4, ஆ-3, இ-2, ஈ-1 ஆகும்.","difficulty":"hard","topic":"திருக்குறள் – பொருத்துக"},{"id":500,"subject":"tamil","testNumber":5,"question":"பொருத்துக (திருக்குறள் உவமை – இடம்பெறும் அதிகாரம்):\nஅ) அனிச்ச மலர் — 1) காலமறிதல்\nஆ) ஆமை — 2) கல்வி\nஇ) மணற்கேணி — 3) அடக்கமுடைமை\nஈ) கொக்கு — 4) விருந்தோம்பல்","options":["அ-4, ஆ-2, இ-3, ஈ-1","அ-3, ஆ-4, இ-2, ஈ-1","அ-4, ஆ-3, இ-1, ஈ-2","அ-4, ஆ-3, இ-2, ஈ-1"],"correctAnswer":3,"explanation":"மோப்பக் குழையும் அனிச்சம் (குறள் 90) – விருந்தோம்பல்; ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் (குறள் 126) – அடக்கமுடைமை; தொட்டனைத் தூறும் மணற்கேணி (குறள் 396) – கல்வி; கொக்கொக்க கூம்பும் பருவத்து (குறள் 490) – காலமறிதல். எனவே சரியான பொருத்தம் அ-4, ஆ-3, இ-2, ஈ-1 ஆகும்.","difficulty":"hard","topic":"திருக்குறள் – பொருத்துக"}]);
